inline void enc_request_identity(std::string& out, const RequestIdentity& v, int depth) {
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "key");
    out += ": ";
    esc(out, v.key);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "history_epoch");
    out += ": ";
    esc(out, v.history_epoch);
    if (v.attempt != 0) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "attempt");
        out += ": ";
        num(out, v.attempt);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

inline void enc_submission(std::string& out, const Submission& v, int depth) {
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "identity");
    out += ": ";
    enc_request_identity(out, v.identity, depth + 1);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "kind");
    out += ": ";
    esc(out, v.kind);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "spec");
    out += ": ";
    esc(out, encode_binary(v.spec));
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "required_guarantees");
    out += ": ";
    strs(out, v.required_guarantees, depth + 1);
    if (!v.label.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "label");
        out += ": ";
        esc(out, v.label);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

