inline RequestIdentity decode_request_identity(Reader& r) {
    if (r.at() != '{') r.refuse("wrong_type");
    r.enter();
    ++r.pos;
    RequestIdentity v;
    std::uint32_t seen = 0;
    r.skip_ws();
    if (r.at() != '}') {
        for (;;) {
            r.skip_ws();
            if (r.at() != '"') r.refuse("malformed");
            const std::string key = r.str();
            r.skip_ws();
            if (r.at() != ':') r.refuse("malformed");
            ++r.pos;
            r.skip_ws();
            if (key == "key") {
                if (seen & 1u) r.refuse("duplicate_field");
                seen |= 1u;
                v.key = r.str();
            } else if (key == "history_epoch") {
                if (seen & 2u) r.refuse("duplicate_field");
                seen |= 2u;
                v.history_epoch = r.str();
            } else if (key == "attempt") {
                if (seen & 4u) r.refuse("duplicate_field");
                seen |= 4u;
                v.attempt = r.integer(INT64_MIN, INT64_MAX);
            } else {
                r.refuse("unknown_field");
            }
            r.skip_ws();
            if (r.at() != ',') break;
            ++r.pos;
        }
    }
    if (r.at() != '}') r.refuse("malformed");
    ++r.pos;
    --r.depth;
    if ((seen & 3u) != 3u) r.refuse("missing_field");
    return v;
}

inline Submission decode_submission(Reader& r) {
    if (r.at() != '{') r.refuse("wrong_type");
    r.enter();
    ++r.pos;
    Submission v;
    std::uint32_t seen = 0;
    r.skip_ws();
    if (r.at() != '}') {
        for (;;) {
            r.skip_ws();
            if (r.at() != '"') r.refuse("malformed");
            const std::string key = r.str();
            r.skip_ws();
            if (r.at() != ':') r.refuse("malformed");
            ++r.pos;
            r.skip_ws();
            if (key == "identity") {
                if (seen & 1u) r.refuse("duplicate_field");
                seen |= 1u;
                v.identity = decode_request_identity(r);
            } else if (key == "kind") {
                if (seen & 2u) r.refuse("duplicate_field");
                seen |= 2u;
                v.kind = r.str();
            } else if (key == "spec") {
                if (seen & 4u) r.refuse("duplicate_field");
                seen |= 4u;
                v.spec = decode_binary(r.str());
            } else if (key == "required_guarantees") {
                if (seen & 8u) r.refuse("duplicate_field");
                seen |= 8u;
                v.required_guarantees = r.str_list();
            } else if (key == "label") {
                if (seen & 16u) r.refuse("duplicate_field");
                seen |= 16u;
                v.label = r.str();
            } else {
                r.refuse("unknown_field");
            }
            r.skip_ws();
            if (r.at() != ',') break;
            ++r.pos;
        }
    }
    if (r.at() != '}') r.refuse("malformed");
    ++r.pos;
    --r.depth;
    if ((seen & 15u) != 15u) r.refuse("missing_field");
    return v;
}

